INSERT INTO `product_translations` (`id`, `title`, `description`, `product_id`, `locale`, `created_at`, `updated_at`) VALUES (130,'Women\'s Handbag','<li data-start=\"434\" data-end=\"646\" style=\"font-weight: 400; letter-spacing: normal; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0);\"><p data-start=\"436\" data-end=\"646\">A stylish handbag made from high-quality materials, perfect for daily use and special occasions. It features a modern design and spacious interior to carry all your essentials with ease.</p></li><li data-start=\"648\" data-end=\"902\" style=\"font-weight: 400; letter-spacing: normal; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0);\"><p data-start=\"650\" data-end=\"902\"><strong data-start=\"650\" data-end=\"666\"></strong></p></li><br class=\"Apple-interchange-newline\" style=\"caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-weight: 400; letter-spacing: normal;\">',44,'en','2025-03-12 11:20:53','2025-03-12 11:20:53'),(131,'حقيبة يد نسائية','<span style=\"font-weight: 400; letter-spacing: normal; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-size: medium;\">حقيبة يد أنيقة مصنوعة من مواد عالية الجودة، مثالية للاستخدام اليومي والمناسبات الخاصة. تتميز بتصميم عصري ومساحة واسعة لحمل جميع احتياجاتك بسهولة.</span>',44,'ar','2025-03-12 11:20:53','2025-03-12 11:20:53'),(132,'Sac à main pour femme','<span style=\"font-weight: 400; letter-spacing: normal; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-size: medium;\">Un sac à main élégant fabriqué à partir de matériaux de haute qualité, idéal pour un usage quotidien et les occasions spéciales. Il offre un design moderne et un intérieur spacieux pour transporter facilement tous vos essentiels.</span>',44,'fr','2025-03-12 11:20:53','2025-03-12 11:20:53'),(139,'Men\'s Jacket','<span style=\"font-weight: 400; letter-spacing: normal; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-size: medium;\">A stylish and modern men\'s jacket made from high-quality materials to provide warmth and comfort. Designed for both casual and formal looks, making it a perfect choice for all seasons and occasions.</span>',47,'en','2025-03-12 12:49:23','2025-03-12 12:49:23'),(140,'جاكيت رجالي','<span style=\"font-weight: 400; letter-spacing: normal; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-size: medium;\">جاكيت رجالي أنيق وعصري مصنوع من خامات عالية الجودة ليمنحك الدفء والراحة. يتميز بتصميم أنيق يناسب الإطلالات الكاجوال والرسمية، مما يجعله خيارًا مثاليًا لجميع الفصول والمناسبات.</span>',47,'ar','2025-03-12 12:49:23','2025-03-12 12:49:23'),(141,'Veste pour homme','<span style=\"font-weight: 400; letter-spacing: normal; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-size: medium;\">Une veste pour homme élégante et moderne, fabriquée à partir de matériaux de haute qualité pour offrir chaleur et confort. Son design sophistiqué convient aussi bien aux tenues décontractées que formelles, idéale pour toutes les saisons et occasions.</span>',47,'fr','2025-03-12 12:49:23','2025-03-12 12:49:23'),(142,'Women\'s Dress','<span style=\"font-weight: 400; letter-spacing: normal; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-size: medium;\">A stylish and elegant women\'s dress designed with premium fabrics to give you a sophisticated and charming look. Featuring a feminine cut that suits various occasions, from parties to chic everyday wear.</span>',48,'en','2025-03-12 12:52:40','2025-03-12 12:52:40'),(143,'فستان نسائي','<span style=\"font-weight: 400; letter-spacing: normal; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-size: medium;\">فستان أنيق وعصري مصمم بأجود الخامات ليمنحك مظهرًا راقيًا وجذابًا. يتميز بقصة أنثوية رائعة تناسب مختلف المناسبات، سواء كانت حفلات أو إطلالات يومية مميزة.</span>',48,'ar','2025-03-12 12:52:40','2025-03-12 12:52:40'),(144,'Robe pour femme','<span style=\"font-weight: 400; letter-spacing: normal; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-size: medium;\">Une robe élégante et moderne, conçue avec des tissus de qualité supérieure pour un look raffiné et séduisant. Sa coupe féminine s’adapte à toutes les occasions, qu\'il s\'agisse de soirées ou de tenues quotidiennes chics.</span>',48,'fr','2025-03-12 12:52:40','2025-03-12 12:52:40'),(157,'Denim Jacket','<span style=\"font-weight: 400; letter-spacing: normal; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-size: medium;\">Elevate your casual style with this trendy denim jacket! Made from high-quality materials for ultimate comfort and durability. Its classic design makes it perfect for everyday wear. Pair it with a t-shirt or shirt for a stylish look that suits all seasons.</span>',53,'en','2025-03-12 21:10:21','2025-03-12 21:10:21'),(158,'جاكت جينز','<span style=\"font-weight: 400; letter-spacing: normal; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-size: medium;\">تألق بإطلالة كاجوال أنيقة مع هذا الجاكت الجينز العصري! مصنوع من خامات عالية الجودة ليمنحك الراحة والمتانة، بتصميم كلاسيكي يناسب جميع المناسبات اليومية. ارتديه مع تيشيرت أو قميص لإطلالة مميزة تناسب جميع الفصول.</span>',53,'ar','2025-03-12 21:10:21','2025-03-12 21:10:21'),(159,'Veste en jean','<span style=\"font-weight: 400; letter-spacing: normal; caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-size: medium;\">Mettez en valeur votre style décontracté avec cette veste en jean tendance ! Fabriquée à partir de matériaux de haute qualité pour un confort et une durabilité exceptionnels. Son design classique la rend parfaite pour toutes les occasions. Associez-la à un t-shirt ou une chemise pour un look élégant adapté à toutes les saisons.</span>',53,'fr','2025-03-12 21:10:21','2025-03-12 21:10:21'),(163,'Men\'s Shirt','A stylish men\'s shirt made from high-quality materials for ultimate comfort and elegance. Featuring a modern design suitable for both formal and casual occasions, making it a perfect addition to your wardrobe.',55,'en','2025-03-12 22:18:16','2025-03-12 22:18:16'),(164,'قميص رجالي','قميص رجالي أنيق مصنوع من أجود الخامات لضمان الراحة والأناقة. يتميز بتصميم عصري يناسب جميع المناسبات الرسمية والكاجوال، مما يجعله إضافة مثالية لخزانة ملابسك.',55,'ar','2025-03-12 22:18:16','2025-03-12 22:18:16'),(165,'Chemise pour homme','Une chemise pour homme élégante fabriquée à partir de matériaux de haute qualité pour un confort et une élégance incomparables. Son design moderne convient aussi bien aux occasions formelles que décontractées, un incontournable de votre garde-robe.',55,'fr','2025-03-12 22:18:16','2025-03-12 22:18:16'),(404,'SGIN 17.3 Inch Laptop Computer,','Laptop 17 inch screen: Experience the best of laptops on sale with this 17 inch laptop Computer, featuring a 1920×1080 HD IPS display for breathtaking clarity. Ideal for laptop for college students and professionals, it provides the perfect balance of performance and portability for work, study, and entertainmentPowerful Intel i3-5005U Processor: This win 11 laptop is powered by an Intel Core i3-5005U processor with 2.4GHz Turbo Boost, offering dual-core, four-thread performance for seamless multitasking. Easily handle 20+ Chrome tabs, video editing, and demanding workloads with desktop-level efficiencyFlexible Storage Options: Equipped with 4GB RAM and 128GB SSD, SGIN laptop supports expansion up to 1TB SSD, ensuring ample storage and lightning-fast performance. An additional SSD slot allows for easy upgrades. As a laptop for work, it guarantees a smooth workflow, keeping your creativity and productivity on trackLong Lasting Battery: Equipped with a 8000 mWh lithium-ion battery, long battery life. SGIN laptop has a long battery life and reliable performance. It features a Type-C port, HDMI (for external monitors/projectors), dual USB 3.2 ports, a 3.5mm headphone jack, and a MicroSD card slot (expandable up to 512GB)After-Sales Support: This win laptop includes a 1-year comprehensive after-sales covering essential components. Our professional customer service team responds within 12 hours, ensuring your electronics device remains in optimal condition',116,'en','2025-09-18 14:47:06','2025-09-21 20:05:21'),(405,'لابتوب اس جي اي ان 17.3 انش،','شاشة لابتوب 17 انش: جرب أفضل أجهزة اللاب توب المعروضة للبيع مع هذا الكمبيوتر المحمول مقاس 17 انش، والذي يتميز بشاشة HD IPS 1920 × 1080 للحصول على وضوح مذهل. مثالي للاب توب لطلاب الجامعات والمحترفين، فهو يوفر التوازن المثالي بين الأداء وسهولة الحمل للعمل والدراسة والترفيهمعالج انتل i3-5005U قوي: يعمل هذا اللاب توب ويندوز 11 بمعالج انتل كور i3-5005U مع تعزيز تربو 2.4 جيجاهرتز، مما يوفر أداءً ثنائي النواة رباعي الخيوط لتعدد المهام بسلاسة. التعامل بسهولة مع أكثر من 20 علامة تبويب كروم وتحرير الفيديو وأعباء العمل الصعبة بكفاءة على مستوى سطح المكتبخيارات تخزين مرنة: مزود بذاكرة رام 4 جيجابايت وهارد SSD 128 جيجابايت، يدعم لابتوب اس جي اي ان التوسع حتى 1 تيرابايت اس اس دي، مما يضمن مساحة تخزين واسعة وأداء فائق السرعة. فتحة SSD إضافية تسمح بسهولة الترقيات. كلاب توب للعمل، فإنه يضمن سير عمل سلس، مما يحافظ على إبداعك وإنتاجيتك على المسار الصحيحبطارية تدوم طويلاً: مجهزة ببطارية ليثيوم أيون 8000 مللي واط في الساعة، عمر بطارية طويل. يتميز لابتوب اس جي اي ان بعمر بطارية طويل وأداء موثوق. يتميز بمنفذ نوع سي ومنفذ HDMI (للشاشات الخارجية/أجهزة العرض)، ومنافذ USB 3.2 مزدوجة، ومقبس سماعة رأس 3.5 ملم، وفتحة بطاقة مايكرو اس دي (قابلة للتوسيع حتى 512 جيجابايت)دعم ما بعد البيع: يتضمن هذا الكمبيوتر المحمول الذي يعمل بنظام وين تغطية شاملة لما بعد البيع لمدة عام واحد تغطي المكونات الأساسية. يستجيب فريق خدمة العملاء المحترف لدينا في غضون 12 ساعة، مما يضمن بقاء جهازك الإلكتروني في حالة مثالية',116,'ar','2025-09-18 14:47:06','2025-09-21 20:05:21'),(406,'Blackview Laptop 2025, Laptops Computer for Business Student','【Powerful Performance】 The Blackview Acebook6 laptop is powered by the 2025 Intel N150 processor (4 cores, up to 3.6GHz, 6MB Cache), engineered for real-world speed and efficiency. With Intel 10nm ultra efficient architecture, it delivers 20% faster multitasking and graphics performance than N4020/J4005/J4105/N5095/N95/N97/N100 laptops. The laptop computer effortlessly handles office tasks, online classes, and streaming. The 6W low-power design ensures long battery life while running cool and quiet, eliminating lag. Ideal for business professionals and students.【16GB DDR4 & 256GB SSD】This computer comes equipped with 16GB DDR4 RAM (2666MHz) for seamless multitasking and a 256GB M.2 SSD for rapid booting and file transfers 3x faster than HDDs. This traditional laptop computer delivers up to 50% better performance than DDR3 computers, ensuring smooth system operation and efficient handling of personal files. Supports 32GB RAM +2TB SSD upgrades, never run out of space for projects or media.【FHD IPS & TÜV Rheinland Eye Care Display】This business & student laptop features a 15.6\" Full HD IPS display (1920x1080, 220 nits, 45% NTSC) with TÜV Rheinland-certified low blue light technology and ultra-narrow bezels (84% screen-to-body ratio). The windows laptop delivers crystal-clear visuals while reducing eye strain, protecting your eyes during long work or study sessions. Equipped with Intel UHD Graphics supporting 4K output via HDMI, it provides immersive HD visuals for multimedia streaming, presentations, and productivity tasks.【Fast Charging & High-Capacity Battery】This Windows 11 laptop features a 5000mAh (38Whr) high-capacity battery and 45W Type-C fast charging (PD 3.0 compliant, with 100W fast charging support)—reaching 60% charge in just 45 minutes, 2.5x faster than traditional DC adapters. Ideal for busy professionals and students, it delivers all-day productivity with minimal downtime—perfect for back-to-back meetings, lectures, or remote work where charging opportunities are limited.【Efficient Cooling & Whisper-Quiet Operation】Engineered with a dual copper tube + fan cooling system and 16,800mm² total heat dissipation area, this computadora maintains optimal performance even during extended work or study sessions—preventing overheating while editing documents, streaming lectures, or running multitab workflows. The intelligent thermal management automatically adjusts fan speed based on usage, ensuring noise levels stay below 43dB. The copper tubing efficiently dissipates heat from the CPU and GPU, keeping temperatures stable during intensive tasks.【Portable Design & Modern Connectivity】Featuring a slim 19.5mm profile and 1.7kg lightweight build, the traditional laptops offer effortless portability for on-the-go tasks. The 180° lay-flat hinge enables easy content sharing in meetings, classrooms, or collaborative settings. Equipped with full-function connectivity, it includes: Type-C (PD 3.0), 2x USB 3.2 Gen1 ports, 1x USB 2.0 port, HDMI 2.0, 3.5mm audio jack, and TF card slot. Dual-band Wi-Fi and Bluetooth 5.0 ensure fast, stable wireless connections. Pre-installed with Windows 11 Home, it delivers a familiar, productive computing experience right out of the box.【24-Month Warranty & Comprehensive Support】Enjoy 24-month repair warranty for manufacturer defects, backed by 12+ years of tech expertise. As a Blackview laptop, it’s supported by our global offline stores—with dedicated locations across the U.S.—for in-person assistance. Our team provides lifetime technical support, including setup guidance and troubleshooting responses within 24 hours (Mon-Sat). We’re committed to assisting with questions and resolving issues efficiently.【Perfect Back-to-School Gift & Daily Use】Whether back-to-school season or daily life, Blackview Acebook 6 laptop fits seamlessly—ideal for students, remote workers, or anyone needing reliability. For students, its 15.6\" TÜV eye-care display eases long study sessions; 16GB RAM handles notes, research, and courses effortlessly. Lightweight and compact, it slides into backpacks for campus or commutes. Beyond school, it excels at work, streaming, and more—practical year-round. Sleek and functional, it’s a thoughtful gift for anyone seeking efficiency and portability, no matter the season.',117,'en','2025-09-18 14:52:21','2025-09-21 20:05:00'),(407,'بلاك فيو لابتوب 2025، لابتوب لطلاب الاعمال،','【أداء قوي】 يعمل لاب توب بلاك فيو Acebook6 بمعالج انتل N150 2025 (رباعي النواة، حتى 3.6 جيجاهرتز، ذاكرة تخزين مؤقتة 6 ميجابايت)، مصمم للسرعة والكفاءة في العالم الحقيقي. مع بنية انتل فائقة الكفاءة 10 نانومتر، فإنها توفر أداء رسومات وتعدد المهام أسرع بنسبة 20% من أجهزة اللاب توب N4020/J4005/J4105/N5095/N95/N97/N100. يتعامل الكمبيوتر المحمول مع المهام المكتبية والدروس عبر الإنترنت والبث دون عناء. يضمن التصميم منخفض الطاقة بقدرة 6 واط عمر بطارية طويل أثناء التشغيل البارد والهدوء، مما يقلل من التأخير. مثالية لمحترفي الأعمال والطلاب.【16GB DDR4 و256GB SSD】يأتي هذا الكمبيوتر مزودًا بذاكرة RAM DDR4 سعة 16GB (2666 ميجاهرتز) لتعدد المهام بسلاسة وهارد SSD M.2 سعة 256GB للتشغيل السريع ونقل الملفات أسرع 3 مرات من الأقراص الصلبة. يوفر الكمبيوتر المحمول التقليدي هذا أداءً أفضل بنسبة تصل إلى 50% من أجهزة الكمبيوتر DDR3، مما يضمن تشغيل النظام بسلاسة ومعالجة فعالة للملفات الشخصية. يدعم ترقية ذاكرة RAM 32GB + SSD 2TB، لا تنفد مساحة المشاريع أو الوسائط.【شاشة FHD IPS وشاشة تي يو في راينلاند للعناية بالعين】يتميز لابتوب الأعمال والطلاب بشاشة IPS FHD مقاس 15.6 انش (1920 × 1080، 220 وحدة مضيئة في البكسل، 45% ان تي اس سي) مع تقنية الضوء الأزرق المنخفض المعتمدة من تي يو في راينلاند وحواف ضيقة للغاية (نسبة الشاشة إلى الهيكل 84%). يوفر اللاب توب الذي يعمل بنظام ويندوز مرئيات واضحة للغاية مع تقليل إجهاد العين، وحماية عينيك أثناء العمل أو جلسات الدراسة الطويلة. مزود برسومات انتل الترا اتش دي التي تدعم مخرج 4 كيه عبر اتش دي ام اي، ويوفر مرئيات عالية الدقة غامرة لبث الوسائط المتعددة والعروض التقديمية ومهام الإنتاجية.【شحن سريع وبطارية عالية السعة】يتميز لابتوب ويندوز 11 هذا ببطارية عالية السعة 5000 مللي امبير في الساعة (38 واط في الساعة) وشحن سريع 45 واط من النوع C (متوافق مع بي دي 3.0، مع دعم شحن سريع 100 واط) - يصل إلى 60% شحن في 45 دقيقة فقط، أسرع بمقدار 2.5 مرة من محولات التيار المستمر التقليدية. مثالي للمحترفين والطلاب المشغولين، فهو يوفر إنتاجية طوال اليوم مع الحد الأدنى من وقت التوقف - مثالي للاجتماعات أو المحاضرات أو العمل عن بعد حيث تكون فرص الشحن محدودة.【تبريد فعال وتشغيل هادئ للغاية】مصمم بأنبوب نحاسي مزدوج + نظام تبريد مروحة ومنطقة تبديد الحرارة الإجمالية 16,800 ملم مربع، يحافظ هذا الكمبيوتر على الأداء الأمثل حتى أثناء العمل الطويل أو جلسات الدراسة - يمنع ارتفاع درجة الحرارة أثناء تحرير المستندات أو بث المحاضرات أو تشغيل سير العمل متعدد التبويبات. تعمل الإدارة الحرارية الذكية على ضبط سرعة المروحة تلقائيًا بناءً على الاستخدام، مما يضمن بقاء مستويات الضوضاء أقل من 43 ديسيبل. تعمل الأنابيب النحاسية على تبديد الحرارة بكفاءة من وحدة المعالجة المركزية ووحدة معالجة الرسومات الجرافيكية، مما يحافظ على ثبات درجات الحرارة أثناء المهام المكثفة.【تصميم محمول واتصال عصري】تتميز بتصميم نحيف 19.5 ملم وهيكل خفيف الوزن 1.7 كغم، توفر أجهزة اللاب توب التقليدية سهولة الحمل للمهام أثناء التنقل. تتيح المفصلات المسطحة بزاوية 180 درجة مشاركة المحتوى بسهولة في الاجتماعات أو الفصول الدراسية أو الإعدادات التعاونية. مزود باتصال كامل الوظائف، ويشمل: نوع سي (بي دي 3.0)، 2 × منفذ يو اس بي 3.2 الجيل الأول، 1 × منفذ يو اس بي 2.0، اتش دي ام اي 2.0، مقبس صوت 3.5 ملم، وفتحة بطاقة تي اف. يضمن واي فاي ثنائي النطاق وبلوتوث 5.0 اتصالات لاسلكية سريعة ومستقرة. مثبت مسبقًا مع ويندوز 11 هوم، يوفر تجربة حوسبة مألوفة ومنتجة بمجرد إخراجه من الصندوق.【ضمان لمدة 24 شهرًا ودعم شامل】استمتع بضمان إصلاح لمدة 24 شهرًا لعيوب الشركة المصنعة، مدعومة بأكثر من 12 عامًا من الخبرة التقنية. باعتباره لابتوب بلاك فيو فهو مدعوم من متاجرنا العالمية غير المتصلة بالإنترنت - مع مواقع مخصصة في جميع أنحاء الولايات المتحدة - للحصول على مساعدة شخصية. يوفر فريقنا دعمًا فنيًا مدى الحياة، بما في ذلك إرشادات الإعداد واستجابات استكشاف الأخطاء وإصلاحها في غضون 24 ساعة (من الاثنين إلى السبت). نحن ملتزمون بالمساعدة في الأسئلة وحل المشكلات بكفاءة.【هدية مثالية للعودة إلى المدرسة والاستخدام اليومي】سواء كان موسم العودة إلى المدرسة أو الحياة اليومية، فإن لابتوب بلاك فيو Acebook 6 يناسب بسلاسة - مثالي للطلاب أو العاملين عن بُعد أو أي شخص يحتاج إلى الموثوقية. بالنسبة للطلاب، فإن شاشة تي يو في للعناية بالعين مقاس 15.6 انش تسهل جلسات الدراسة الطويلة؛ ذاكرة رام 16 جيجابايت تتعامل مع الملاحظات والأبحاث والدورات التدريبية دون عناء. خفيفة الوزن وصغيرة الحجم، تنزلق في حقائب الظهر للحرم الجامعي أو التنقل. ما بعد المدرسة، فهي تتفوق في العمل والبث وأكثر من ذلك - عملية على مدار العام. أنيقة وعملية، إنها هدية مدروسة لأي شخص يبحث عن الكفاءة وسهولة الحمل، بغض النظر عن الموسم.',117,'ar','2025-09-18 14:52:21','2025-09-21 20:05:00'),(408,'ACEMAGIC 2025 Laptop,17.3-Inch FHD','【Powerful Capabilities】The ACEMAGIC AX17 Traditional laptop computer is equipped with the latest 12th Gen Intel Alder Lake N97 processor (4C/4T, 6MB Cache, 12W, base frequency 1.7GHz, up to 3.6GHz, 7nm process), delivering significantly higher performance than Celeron N5095 or Pentium N5030. With built-in 16GB DDR4 RAM and a 512GB SSD, it offers enhanced power for seamless multitasking.【Immersive IPS Display】This 17.3inch laptop features an innovative thin-bezel design that maximizes the screen area for a truly immersive FHD viewing experience. The compact chassis integrates a larger display while maintaining a smaller footprint. A built-in front-facing webcam, centered above the screen, allows you to easily take photos or join video calls anytime.【Long Battery Life】Take this laptop anywhere without carrying a power adapter. Its 6000mAh battery supports up to 5 hours of continuous use, providing flexibility for work or entertainment on the go. The integrated cooling fans ensure quiet and sustained performance, minimizing distractions whether you’re working on spreadsheets or watching movies.【Seamless Connectivity】This Windows 11 laptop includes a versatile selection of ports: HDMI Type A × 1, USB 3.2 × 3, Type-C (Data Only) × 1, a 3.5mm headphone jack × 1, a 128GB TF card slot × 1, and a DC jack × 1. It supports 802.11ac Wi-Fi for speeds up to three times faster than 802.11n, ensuring high-speed data transmission and downloads. Bluetooth 5.0 enables stable and easy connections with compatible devices.【ACEMAGIC Care For You】Designed with a durable metal casing, this 2025 laptop resists pressure and impacts while remaining slim and lightweight,easy to carry in a backpack wherever you go. We provide lifetime technical support and a 12-month quality warranty. Should you have any questions, feel free to reach out—we’re always here to help.',118,'en','2025-09-18 15:00:11','2025-09-18 15:02:05'),(409,'لابتوب ايس ماجيك 2025 بشاشة FHD 17.3 انش','قدرات قوية】تم تجهيز لابتوب ايه اكس 17 التقليدي من اسيماجيك بأحدث معالج انتل ألدر ليك N97 من الجيل الثاني عشر (4C/4T، ذاكرة تخزين مؤقتة 6 ميجابايت، 12 واط، تردد أساسي 1.7 جيجاهرتز، حتى 3.6 جيجاهرتز، عملية 7 نانومتر)، مما يوفر أداءً أعلى بكثير من سيليرون N5095 أو بنتيوم N5030. مع ذاكرة رام DDR4 مدمجة بسعة 16 جيجابايت وهارد SSD سعة 512 جيجابايت، فإنها توفر قوة معززة لتعدد المهام بسلاسة.【شاشة IPS غامرة】يتميز هذا اللاب توب مقاس 17.3 انش بتصميم مبتكر رفيع الحواف يزيد من مساحة الشاشة لتجربة عرض FHD غامرة حقًا. يدمج الهيكل المدمج شاشة أكبر مع الحفاظ على بصمة أصغر. كاميرا ويب أمامية مدمجة، في المنتصف فوق الشاشة، تسمح لك بالتقاط الصور بسهولة أو الانضمام إلى مكالمات الفيديو في أي وقت.【عمر بطارية طويل】اصطحب هذا اللاب توب إلى أي مكان دون حمل محول طاقة. بطارية 6000mAh تدعم ما يصل إلى 5 ساعات من الاستخدام المستمر، مما يوفر المرونة للعمل أو الترفيه أثناء التنقل. تضمن مراوح التبريد المدمجة أداءً هادئًا ومستدامًا، مما يقلل من التشتيت سواء كنت تعمل على جداول البيانات أو تشاهد الأفلام.【اتصال سلس】يتضمن هذا اللاب توب الذي يعمل بنظام ويندوز 11 مجموعة متنوعة من المنافذ: HDMI Type A × 1، USB 3.2 × 3، نوع C (البيانات فقط) × 1، مقبس سماعة رأس 3.5 ملم × 1، فتحة بطاقة TF 128GB × 1، ومقبس تيار مستمر × 1. يدعم واي فاي 802.11ac لسرعات تصل إلى ثلاث مرات أسرع من 802.11n، مما يضمن نقل البيانات وتنزيلها بسرعة عالية. يتيح بلوتوث 5.0 اتصالات مستقرة وسهلة مع الأجهزة المتوافقة.【عناية رائعة لك】مصمم بغلاف معدني متين، يقاوم هذا اللاب توب 2025 الضغط والتأثيرات مع الحفاظ على النحافة وخفيف الوزن، سهل الحمل في حقيبة الظهر أينما ذهبت. نقدم الدعم الفني مدى الحياة وضمان الجودة لمدة 12 شهرًا. إذا كانت لديك أي أسئلة، فلا تتردد في التواصل معنا - فنحن دائمًا هنا للمساعدة.',118,'ar','2025-09-18 15:00:11','2025-09-18 15:02:05'),(410,'jumper 16 inch Convertible Laptop','1 Year Office 365: Convertible Laptop includes 1 year Office 365 to start using advanced productivity tools right away. Compliment your new laptop with free year-round access to Word, Excel, PowerPoint, Outlook and more. Increased productivity and creativity360° Foldable Notebook: 2 in 1 laptop with four modes of use: laptop, tablet, tent and stand. Laptop with 360° swivel hinge, flexible and free to switch between different modes, can help you improve your work efficiency and recreational use. Very practical16 inch FHD Screen: Folding laptop with 16 inch IPS touchable display with 1920x1200 resolution and narrow bezels for an immersive viewing experience. In addition, the 10 point touch feature enhances usability for browsing and entertainmentMemory & Expandable Storage: Laptop features 16GB DDR4 RAM 640GB storage, with an extra DDR4 slot for expansion (supports up to 16GB). The SSD can also be upgraded to 2TB, ensuring ample space for all your files and eliminating storage concernsCooling System & Secure Login: Touchscreen Laptop is equipped with a fan system at the bottom to help dissipate heat from the computer and make the system run smoother. Computer also has a built in fingerprint reader for quick access without a password',119,'en','2025-09-18 15:07:57','2025-09-21 19:16:18'),(411,'جمبر لابتوب قابل للتحويل مقاس 16 انش','اوفيس 365 لمدة عام واحد: يتضمن الكمبيوتر المحمول القابل للتحويل اوفيس 365 لمدة عام واحد لبدء استخدام أدوات إنتاجية متقدمة على الفور. أكمل اللاب توب الجديد الخاص بك مع إمكانية الوصول المجاني على مدار العام إلى وورد واكسيل وباور بوينت واوت لوك والمزيد. زيادة الإنتاجية والإبداعنوت بوك قابل للطي 360 درجة: لابتوب 2 في 1 مع أربعة أوضاع للاستخدام: اللاب توب والتابلت والخيمة والحامل. لابتوب بمفصلات دوارة 360 درجة، مرن وحرية للتبديل بين الأوضاع المختلفة، يمكن أن يساعدك على تحسين كفاءة العمل والاستخدام الترفيهي. عملي للغايةشاشة FHD مقاس 16 انش: لابتوب قابل للطي بشاشة لمس IPS مقاس 16 انش بدقة 1920 × 1200 وحواف ضيقة لتجربة مشاهدة غامرة. بالإضافة إلى ذلك، تعزز ميزة اللمس المكونة من 10 نقاط سهولة الاستخدام للتصفح والترفيهالذاكرة والتخزين القابل للتوسيع: يتميز اللاب توب بذاكرة رام DDR4 سعة 16 جيجابايت وذاكرة تخزين 640 جيجابايت، مع فتحة DDR4 إضافية للتوسع (يدعم حتى 16 جيجابايت). يمكن أيضًا ترقية SSD إلى 2 تيرابايت، مما يضمن مساحة واسعة لجميع ملفاتك والتخلص من مخاوف التخزيننظام التبريد وتسجيل الدخول الآمن: تم تجهيز لابتوب بشاشة اللمس بنظام مروحة في الأسفل للمساعدة في تبديد الحرارة من الكمبيوتر وجعل النظام يعمل بشكل أكثر سلاسة. يحتوي الكمبيوتر أيضًا على قارئ بصمات الأصابع مدمج للوصول السريع بدون كلمة مرور',119,'ar','2025-09-18 15:07:57','2025-09-21 19:16:18'),(412,'Samsung Galaxy A16 5G A Series','CRISP DETAIL. VIVID POSSIBILITIES: The ultra-clear 6.7\" display¹ of Galaxy A16 5G helps bring your content to life whether you’re checking emails or reading online blogs and recipes.MEMORIES MADE PICTURE PERFECT: Capture every angle in stunning clarity, from big group shots to close-ups, with the triple-lens camera on Galaxy A16 5G.MORE DURABLE THAN EVER BEFORE: Take on your day with confidence, thanks to the awesome durability of Galaxy A16 5G with an improved IP54 rating.²HEALTH INSIGHTS MADE EASY: Stay connected to your health with Galaxy A16 5G and Fit3. Track your steps, sleep and heart rate³ and then see it all in one place with the Samsung Health app.AWESOME EXPERIENCE. AWESOME VALUE: Galaxy A16 5G offers essential features and practical extras designed to enhance your everyday life — all at a price you’ll love.PAYING MAD EASY: Pay with a tap, plus store your cards and ID all in one app with Samsung Wallet.⁴,⁵6X UPDATES. AWESOME SECURITY: 6X of OS and security updates mean you can keep your Galaxy A16 5G longer, making it a great value for years to come.LIVE FAST. CHARGE FASTER: Focus more on the moment and less on your battery percentage with Galaxy A16 5G. Super Fast Charging⁶ powers up your battery at lightning speed so you can get back to life sooner.STORE MORE AND WORRY LESS: With improved internal storage of up to 128GB and up to 1.5TB⁷ of expandable storage, Galaxy A16 5G makes it easy to keep cherished photos, videos and important files readily accessible whenever you need them.',120,'en','2025-09-18 15:16:09','2025-09-21 18:33:44'),(413,'سامسونج جوال جالكسي ايه 16 سلسلة 5G A،','تفاصيل كريسب. إمكانيات حيوية: تساعد شاشة جالكسي ايه 16 الجيل الخامس فائقة الوضوح مقاس 6.7 انش على إضفاء الحيوية على المحتوى الخاص بك سواء كنت تتحقق من رسائل البريد الإلكتروني أو تقرأ المدونات والوصفات عبر الإنترنت.صورة مثالية للذكريات: التقط كل زاوية بوضوح مذهل، من اللقطات الجماعية الكبيرة إلى الصور المقربة، مع الكاميرا ثلاثية العدسات على جالاكسي A16 5G.أكثر متانة من أي وقت مضى: خذ يومك بثقة، بفضل المتانة الرائعة لهاتف جالاكسي A16 5G مع تصنيف IP54 المحسن.²أصبحت الرؤى الصحية سهلة: ابق على اتصال بصحتك مع جالكسي ايه 16 الجيل الخامس وفيت 3. تتبع خطواتك ونومك ومعدل ضربات القلب³ ثم شاهد كل ذلك في مكان واحد باستخدام تطبيق سامسونج Health.تجربة رائعة. قيمة رائعة: يوفر هاتف جالكسي ايه 16 الجيل الخامس ميزات أساسية وإضافات عملية مصممة لتعزيز حياتك اليومية - كل ذلك بسعر ستحبه.الدفع بسهولة: ادفع بنقرة واحدة، بالإضافة إلى تخزين بطاقاتك وهويتك كلها في تطبيق واحد باستخدام سامسونج Wallet.6 أضعاف التحديثات. أمان رائع: 6 أضعاف من تحديثات نظام التشغيل والأمان تعني أنه يمكنك الحفاظ على هاتف جالاكسي A16 5G لفترة أطول، مما يجعله قيمة رائعة لسنوات قادمة.عش بسرعة. شحن أسرع: ركز أكثر على اللحظة وأقل على نسبة البطارية الخاصة بك مع جالكسي ايه 16 الجيل الخامس. شحن فائق السرعة، يعمل على تشغيل بطاريتك بسرعة البرق حتى تتمكن من العودة إلى الحياة في وقت أقرب.تخزين أكثر وأقل قلقًا: بفضل سعة التخزين الداخلية المحسنة التي تصل إلى 128 جيجابايت وما يصل إلى 1.5 تيرابايت من التخزين القابل للتوسيع، فإن هاتف جالكسي ايه 16 الجيل الخامس يجعل من السهل الحفاظ على الصور ومقاطع الفيديو والملفات المهمة في متناول اليد كلما احتجت إليها.',120,'ar','2025-09-18 15:16:09','2025-09-21 18:33:44'),(420,'15.6\" Laptop Computer Notebook,','About this itemPerformance: 16GB DDR4 memory (upgradable to 32GB); 1TB PCIe SSD (upgradable to 8TB); N95 processor (4C/4T, 1.7-3.4 GHz); Win11 Pro preinstalledUsability: Features a backlit keyboard for comfortable typing in low light; and a fingerprint reader for secure, one-touch login; an 8000mAh, 61.6Wh battery for extended useDisplay: 15.6″ Full HD (1920 × 1080) IPS screen with a 0.2 in narrow bezel and 180° hinge; powered by UHD Graphics (16 EU at up to 1.20 GHz) supporting up to three 4K @ 60 Hz external displays for vibrant visuals and flexible viewing anglesMultimedia: Dual 8 Ω/1.0 W stereo speakers and a 300K‑pixel webcam for crisp calls and multimedia playbackConnectivity: Dual‑band 5 GHz Wi‑Fi (802.11ac/g/n) and Bluetooth 5.0 for reliable device pairingPortability: Glass-like touchpad; compact 14 × 9 × 0.7 inches—about the size of a standard magazine; weighs just 3.7 lbs, comparable to a small bag of apples; durable silver plastic body; built-in cooling fan; easy to carry for work or travelPorts: 2× USB 3.0 for fast data transfer; 1× MicroSD slot (supports up to 2 TB); Mini (or standard) HDMI output for 4K video; 3.5 mm audio jack (with microphone, right side); DC 3.5 mm round power port (12V 3A, left side)Included: Auusda T152A Laptop, universal 100-240V charger, keyboard cover, user manual; 24/7 customer service; 100-day free returns; 24-month warranty for worry-free ownership.',124,'en','2025-10-11 17:40:41','2025-10-11 18:18:18'),(421,'لابتوب نوت بوك 15.6 انش','عن هذه السلعةالأداء: ذاكرة DDR4 سعة 16 جيجابايت (قابلة للترقية إلى 32 جيجابايت)؛ وسيط تخزين ذو حالة ثابتة بمنفذ PCIe سعة 1 تيرابايت (قابل للترقية إلى 8 تيرابايت)؛ معالج N95 (4C/4T، 1.7-3.4 GHz)؛ ويندوز 11 برو مثبت مسبقًاقابلية الاستخدام: تتميز بلوحة مفاتيح بإضاءة خلفية لكتابة مريحة في الإضاءة المنخفضة؛ وقارئ بصمات الأصابع لتسجيل الدخول الآمن بلمسة واحدة؛ بطارية 8000mAh، 61.6 واط في الساعة للاستخدام الطويلالشاشة: شاشة IPS FHD مقاس 15.6 انش (1920 × 1080) بإطار ضيق 0.2 انش ومفصلة 180 درجة؛ مدعومة برسومات UHD (16 EU بسرعة تصل إلى 1.20 GHz) تدعم ما يصل إلى ثلاث شاشات خارجية بدقة 4K @ 60 هرتز للحصول على صور نابضة بالحياة وزوايا رؤية مرنةالوسائط المتعددة: مكبرات صوت ستيريو مزدوجة 8 Ω/1.0 واط وكاميرا ويب 300K بكسل لإجراء مكالمات واضحة وتشغيل الوسائط المتعددةالاتصال: واي فاي ثنائي النطاق 5 جيجاهرتز (802.11ac/g/n) وبلوتوث 5.0 للاقتران الموثوق للأجهزةقابلية الحمل: لوحة لمس تشبه الزجاج؛ صغيرة الحجم 14 × 9 × 0.7 انش - بحجم مخزن قياسي؛ تزن 3.7 باوند فقط، مقارنة بكيس التفاح الصغير؛ هيكل بلاستيكي فضي متين؛ مروحة تبريد مدمجة؛ سهلة الحمل للعمل أو السفرالمنافذ: 2 × USB 3.0 لنقل البيانات بسرعة؛ 1 × فتحة مايكرو اس دي (تدعم حتى 2 تيرابايت)؛ مخرج HDMI صغير (أو قياسي) لفيديو 4K؛ مقبس صوت 3.5 ملم (مع ميكروفون، الجانب الأيمن)؛ منفذ طاقة دائري تيار مستمر 3.5 ملم (12 فولت 3 امبير، الجانب الأيسر)يشتمل على: لابتوب اوسدا T152A، شاحن عالمي 100-240 فولت، غطاء كيبورد، دليل المستخدم؛ خدمة عملاء على مدار الساعة طوال أيام الأسبوع؛ إرجاع مجاني لمدة 100 يوم؛ ضمان لمدة 24 شهرًا لملكية خالية من القلق.',124,'ar','2025-10-11 17:40:41','2025-10-11 18:18:18'),(422,'HP Stream 14\" HD','About this item【Upgraded】Seal is opened for upgrade only, 1-Year warranty on Upgraded RAM/SSD from SnowBell, and original 1-Year Manufacture warranty on remaining components.【14\" HD Micro-edge Anti-glare Display】14-inch diagonal, HD (1366 x 768), micro-edge, anti-glare display. The anti-glare technology reduces ambient light reflection, ensuring clear visibility even in strong light.【Intel Processor N150】Adopting a high-performance architecture, it supports multi-threaded processing, ensuring smooth operation for daily office tasks, web browsing, and lightweight applications. The low-power design extends battery life, balancing performance and energy efficiency.【8GB DDR4 RAM】Sufficient bandwidth ensures smooth and unhindered concurrent operation of multiple programs, effortlessly handling multitasking scenarios.【288GB Storage(128GB UFS+160GB Docking Station Set)】High-speed solid-state architecture for fast read, shorter loading times, smooth daily office/web/light app use, and extended battery life via low power consumption.【Intel Graphics】Integrated graphics for HD video playback and daily graphics tasks. Low-power design fits thin devices, meets office/entertainment needs with energy efficiency.【1 Year Office 365】Take your productivity and work mobility to the next level with the Microsoft 365 Office Suite (1 year subscription included).【Windows 11 S】Faster startup, optimized performance for education and business use.12.76 x 8.86 x 0.71 inches, 3.24 lbs.【Ports】1x USB Type-C, 2x USB Type-A, 1x Headphone/microphone combo, 1x Media card reader, 1x HDMI 1.4b, 1x AC Smart pin. Wi-Fi 6, Bluetooth, Webcam.【Bonus Docking Station Set】1x 7-in-1 Docking Station w/ 128GB SSD, 1x 32GB MicroSD Card w/ Adapter, 1x Type-C Data Cable, 1x 3-in-1 Charging Cable, 1x Suede Cleaning Cloth.',125,'en','2025-10-11 17:46:31','2025-10-11 18:17:18'),(423,'HP لابتوب ستريم 14 انش','عن هذه السلعة【مطور】يتم فتح الختم للترقية فقط، ضمان لمدة عام على ذاكرة RAM / SSD المطورة من سنوبيل، وضمان المصنع الأصلي لمدة عام على المكونات المتبقية. 【شاشة HD مضادة للتوهج بحواف دقيقة مقاس 14 انش】قطر 14 انش، HD (1366 × 768)، شاشة مايكرو ايدج مضادة للتوهج. تقلل التقنية المضادة للوهج من انعكاس الضوء المحيط، مما يضمن رؤية واضحة حتى في الإضاءة القوية.【معالج انتل N150】يعتمد على بنية عالية الأداء، فهو يدعم معالجة متعددة الخيوط، مما يضمن التشغيل السلس للمهام المكتبية اليومية وتصفح الويب والتطبيقات خفيفة الوزن. يعمل التصميم منخفض الطاقة على إطالة عمر البطارية، ويوازن الأداء وكفاءة الطاقة.【ذاكرة رام DDR4 سعة 8 جيجابايت】يضمن عرض النطاق الترددي الكافي التشغيل المتزامن السلس وغير المقيد للبرامج المتعددة، والتعامل مع سيناريوهات تعدد المهام دون عناء. 【تخزين 288 جيجابايت (مجموعة قاعدة شحن يو اف اس 128 جيجابايت + 160 جيجابايت)】بنية الحالة الصلبة عالية السرعة للقراءة السريعة وأوقات تحميل أقصر واستخدام يومي سلس للمكتب / الويب / تطبيق الضوء وعمر بطارية طويل من خلال استهلاك منخفض للطاقة.【بطاقة رسومات انتل】رسومات مدمجة لتشغيل الفيديو عالي الدقة ومهام الرسومات اليومية. تصميم منخفض الطاقة يناسب الأجهزة الرفيعة، ويلبي احتياجات المكتب/الترفيه بكفاءة استخدام الطاقة.【مكتب 365 لمدة عام واحد】ارتقِ بإنتاجيتك وحركتك في العمل إلى المستوى التالي مع مايكروسوفت 365 اوفيس سويت (اشتراك لمدة عام واحد).【ويندوز 11 اس】بدء تشغيل أسرع، أداء محسن للاستخدام التعليمي والعمل. 12.75 × 8.86 × 0.71 انش، 3.3 باوند【المنافذ】1 × USB نوع C، 2 × USB نوع A، 1 × مجموعة سماعة رأس/ميكروفون، 1 × قارئ بطاقة وسائط، 1 × HDMI 1.4b، 1 × دبوس ذكي تيار متردد. واي فاي 6، بلوتوث، كاميرا ويب.【مجموعة قاعدة شحن إضافية】1 × قاعدة شحن 7 في 1 مع هارد SSD 128 جيجابايت، 1 × بطاقة مايكرو اس دي 32 جيجابايت مع محول، 1 × كيبل بيانات من النوع سي، 1 × كابل شحن 3 في 1، 1 × قطعة قماش للتنظيف من الشامواه.',125,'ar','2025-10-11 17:46:31','2025-10-11 18:17:18'),(424,'HP Stream 14\" HD Laptop for Student & Business','About this item【Upgraded】Seal is opened for upgrade only, 1-Year warranty on Upgraded RAM/SSD from SnowBell, and original 1-Year Manufacture warranty on remaining components.【14\" HD Micro-edge Anti-glare Display】14-inch diagonal, HD (1366 x 768), micro-edge, anti-glare display. The anti-glare technology reduces ambient light reflection, ensuring clear visibility even in strong light.【Intel Processor N150】Adopting a high-performance architecture, it supports multi-threaded processing, ensuring smooth operation for daily office tasks, web browsing, and lightweight applications. The low-power design extends battery life, balancing performance and energy efficiency.【8GB DDR4 RAM】Sufficient bandwidth ensures smooth and unhindered concurrent operation of multiple programs, effortlessly handling multitasking scenarios.【288GB Storage(128GB UFS+160GB Docking Station Set)】High-speed solid-state architecture for fast read, shorter loading times, smooth daily office/web/light app use, and extended battery life via low power consumption.【Intel Graphics】Integrated graphics for HD video playback and daily graphics tasks. Low-power design fits thin devices, meets office/entertainment needs with energy efficiency.【1 Year Office 365】Take your productivity and work mobility to the next level with the Microsoft 365 Office Suite (1 year subscription included).【Windows 11 S】Faster startup, optimized performance for education and business use.12.76 x 8.86 x 0.71 inches, 3.24 lbs.【Ports】1x USB Type-C, 2x USB Type-A, 1x Headphone/microphone combo, 1x Media card reader, 1x HDMI 1.4b, 1x AC Smart pin. Wi-Fi 6, Bluetooth, Webcam.【Bonus Docking Station Set】1x 7-in-1 Docking Station w/ 128GB SSD, 1x 32GB MicroSD Card w/ Adapter, 1x Type-C Data Cable, 1x 3-in-1 Charging Cable, 1x Suede Cleaning Cloth.',126,'en','2025-10-11 17:52:39','2025-10-11 18:12:55'),(425,'HP لابتوب ستريم 14 انش HD للطلاب والاعمال','عن هذه السلعة【مطور】يتم فتح الختم للترقية فقط، ضمان لمدة عام على ذاكرة RAM / SSD المطورة من سنوبيل، وضمان المصنع الأصلي لمدة عام على المكونات المتبقية. 【شاشة HD مضادة للتوهج بحواف دقيقة مقاس 14 انش】قطر 14 انش، HD (1366 × 768)، شاشة مايكرو ايدج مضادة للتوهج. تقلل التقنية المضادة للوهج من انعكاس الضوء المحيط، مما يضمن رؤية واضحة حتى في الإضاءة القوية.【معالج انتل N150】يعتمد على بنية عالية الأداء، فهو يدعم معالجة متعددة الخيوط، مما يضمن التشغيل السلس للمهام المكتبية اليومية وتصفح الويب والتطبيقات خفيفة الوزن. يعمل التصميم منخفض الطاقة على إطالة عمر البطارية، ويوازن الأداء وكفاءة الطاقة.【ذاكرة رام DDR4 سعة 8 جيجابايت】يضمن عرض النطاق الترددي الكافي التشغيل المتزامن السلس وغير المقيد للبرامج المتعددة، والتعامل مع سيناريوهات تعدد المهام دون عناء. 【تخزين 288 جيجابايت (مجموعة قاعدة شحن 128 جيجابايت + 160 جيجابايت)】بنية الحالة الصلبة عالية السرعة للقراءة السريعة وأوقات تحميل أقصر واستخدام يومي سلس للمكتب / الويب / تطبيق الضوء وعمر بطارية طويل من خلال استهلاك منخفض للطاقة.【بطاقة رسومات انتل】رسومات مدمجة لتشغيل الفيديو عالي الدقة ومهام الرسومات اليومية. تصميم منخفض الطاقة يناسب الأجهزة الرفيعة، ويلبي احتياجات المكتب/الترفيه بكفاءة استخدام الطاقة.【مكتب 365 لمدة عام واحد】ارتقِ بإنتاجيتك وحركتك في العمل إلى المستوى التالي مع مايكروسوفت 365 اوفيس سويت (اشتراك لمدة عام واحد).【ويندوز 11 اس】بدء تشغيل أسرع، أداء محسن للاستخدام التعليمي والعمل. 12.75 × 8.86 × 0.71 انش، 3.3 باوند【المنافذ】1 × USB نوع C، 2 × USB نوع A، 1 × مجموعة سماعة رأس/ميكروفون، 1 × قارئ بطاقة وسائط، 1 × HDMI 1.4b، 1 × دبوس ذكي تيار متردد. واي فاي 6، بلوتوث، كاميرا ويب.【مجموعة قاعدة شحن إضافية】1 × قاعدة شحن 7 في 1 مع هارد SSD 128 جيجابايت، 1 × بطاقة مايكرو اس دي 32 جيجابايت مع محول، 1 × كيبل بيانات من النوع سي، 1 × كابل شحن 3 في 1، 1 × قطعة قماش للتنظيف من الشامواه.',126,'ar','2025-10-11 17:52:39','2025-10-11 18:12:55'),(426,'LG gram Pro 16-inch Lightweight Laptop Computer','<h2 class=\"a-size-base-plus a-text-bold\" style=\"padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding-block-end: 0.25rem; text-rendering: optimizelegibility; color: rgb(15, 17, 17); letter-spacing: normal; text-transform: none; font-weight: 700 !important; font-size: 1.25rem !important; line-height: 24px !important; font-family: &quot;Amazon Ember&quot; !important;\">About this item</h2><ul class=\"a-unordered-list a-vertical a-spacing-mini\" style=\"margin-right: 0px; margin-left: 18px; color: rgb(15, 17, 17); padding-top: 0px; padding-bottom: 0px; font-family: &quot;Amazon Ember&quot;, Arial, sans-serif; font-weight: 400; letter-spacing: normal;\"><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">Pro AI Anywhere - LG gram Pro pairs ultra-light design with powerful AI performance. Weighing 2.7 lbs. and featuring a 16” IPS display, it’s built for productivity anywhere. With the Intel Core Ultra 7 processor and LG gram AI solutions, experience both on-device and cloud-powered AI for versatile AI performance.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">Reimagine Productivity with AI-Powered Copilot+ PC on Windows 11 - AI Copilot+ PC redefines what your laptop can do. Built with advanced AI hardware, Windows 11 tools, and long battery life, it’s the ultimate laptop optimized AI workloads, for smarter work, seamless multitasking, and creative breakthroughs</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">Hybrid AI: On-Device and Cloud Synergy - LG gram now includes a hybrid AI solution that blends on-device intelligence with the capabilities of cloud-based AI. gram chat On-Device manages local tasks like smart hard drive searches and system adjustments, while gram chat Cloud delivers generative AI responses for document creation, data analysis, and administrative tasks like scheduling—all through intuitive interactions.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">Born for AI, perfectly paired with Intel Evo Edition Intel Core Ultra (Series 2) - Intel Evo Edition - Intel Core Ultra 7 processor (Series 2) with 47 NPU TOPS is a groundbreaking processor for PCs, delivering powerful AI performance compared to previous generations, enabling the capabilities required for an enhanced Copilot+ PC experience. With power and distinct performance of an AI-dedicated processor, this gram Pro efficiently handles AI and machine learning tasks.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">Unbelievably Portable. Undeniably Strong. - The LG gram Pro laptop packs incredible performance into a half-inch-thin, 2.7 lbs. frame that’s passed seven military-grade standards for resilience and durability. From your desk to the road, gram Pro is built to go wherever you work and play.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">The Power to Stay Unplugged - Powered by a 77Wh high-capacity battery offering up to 25.5 hours of video playback and equipped with our AI Smart Assistant, gram analyzes user patterns to optimize battery efficiency. Boost your productivity and enjoy uninterrupted play.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">Internal Dual Cooling System - LG gram Pro\'s internal cooling system keeps the laptop running efficiently and helps prevent overheating</span></li></ul>',127,'en','2025-10-11 17:54:42','2025-10-11 17:54:42'),(427,'LG لابتوب جرام برو خفيف الوزن 16 انش','<h2 class=\"a-size-base-plus a-text-bold\" style=\"padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding-block-end: 0.25rem; text-rendering: optimizelegibility; color: rgb(15, 17, 17); letter-spacing: normal; text-transform: none; font-weight: 700 !important; font-size: 1.25rem !important; line-height: 24px !important; font-family: &quot;Amazon Ember&quot; !important;\">عن هذه السلعة</h2><ul class=\"a-unordered-list a-vertical a-spacing-mini\" style=\"margin-right: 18px; margin-left: 0px; color: rgb(15, 17, 17); padding-top: 0px; padding-bottom: 0px; font-family: &quot;Amazon Ember&quot;, Arial, sans-serif; font-weight: 400; letter-spacing: normal;\"><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">تقنية الذكاء الاصطناعي الاحترافية في أي مكان - يجمع LG gram Pro بين التصميم الخفيف للغاية والأداء القوي للذكاء الاصطناعي. تزن 2.6 باوند. وتتميز بشاشة IPS مقاس 16 انش، فهي مصممة للإنتاجية في أي مكان. مع معالج انتل كور الترا 7 وحلول LG gram AI ، جرب الذكاء الاصطناعي على الجهاز والدعم السحابي لأداء ذكاء اصطناعي متعدد الاستخدامات.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">أعد تخيل الإنتاجية مع كوبايلوت + الكمبيوتر الذي يعمل بالذكاء الاصطناعي على ويندوز 11 - يعيد الذكاء الاصطناعي كوبايلوت + الكمبيوتر تعريف ما يمكن أن يفعله اللاب توب. تم تصميمه باستخدام أجهزة الذكاء الاصطناعي المتقدمة، وأدوات ويندوز 11، وعمر بطارية طويل، إنه أفضل أعباء عمل للذكاء الاصطناعي المحسن، لعمل أكثر ذكاءً، وتعدد المهام السلس، والاختراقات الإبداعية</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">الذكاء الاصطناعي الهجين: على الجهاز والتآزر السحابي - يشتمل LG gram الآن على حل ذكاء اصطناعي هجين يمزج بين الذكاء الاصطناعي على الجهاز وقدرات الذكاء الاصطناعي المستند إلى السحابة. يقوم غرام شات اون ديفايس بإدارة المهام المحلية مثل عمليات البحث عن القرص الصلب الذكي وتعديلات النظام، بينما توفر غرام شات كلاود استجابات ذكاء اصطناعي توليدية لإنشاء المستندات وتحليل البيانات والمهام الإدارية مثل الجدولة - كل ذلك من خلال تفاعلات بديهية.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">تم تصميمه خصيصًا للذكاء الاصطناعي، مقترن بشكل مثالي بإصدار انتل كور الترا (السلسلة 2) - إصدار انتل ايفو - معالج انتل كور الترا 7 (السلسلة 2) مع 47 وحدة ان بي يو بي اس هو معالج رائد لأجهزة الكمبيوتر، مما يوفر أداءً قويًا للذكاء الاصطناعي مقارنة بالأجيال السابقة، مما يتيح القدرات المطلوبة لتجربة كوبايلوت + الكمبيوتر المحسنة. بفضل القوة والأداء المتميز للمعالج المخصص للذكاء الاصطناعي، يتعامل غرام برو هذا بكفاءة مع مهام الذكاء الاصطناعي والتعلم الآلي.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">قابلة للحمل بشكل لا يصدق. قوي بشكل لا يمكن إنكاره. يوفر لاب توب LG gram Pro أداءً مذهلاً بسمك نصف بوصة ووزن 2.6 باوند. إطار اجتاز سبعة معايير من الدرجة العسكرية للمرونة والمتانة. من مكتبك إلى الطريق، تم تصميم جرام برو للذهاب أينما كنت تعمل وتلعب.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">القدرة على البقاء غير موصول - تعمل ببطارية عالية السعة 77 واط في الساعة توفر ما يصل إلى 25.5 ساعة من تشغيل الفيديو ومجهزة بمساعد الذكاء الاصطناعي الذكي، يقوم جرام بتحليل أنماط المستخدم لتحسين كفاءة البطارية. عزز إنتاجيتك واستمتع باللعب دون انقطاع.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">نظام التبريد الداخلي المزدوج - يحافظ نظام التبريد الداخلي من LG gram Pro على تشغيل الكمبيوتر المحمول بكفاءة ويساعد على منع ارتفاع درجة الحرارة.</span></li></ul>',127,'ar','2025-10-11 17:54:42','2025-10-11 17:54:42'),(428,'HP Flagship 14\" HD Student&Business Laptop','<h2 class=\"a-size-base-plus a-text-bold\" style=\"padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding-block-end: 0.25rem; text-rendering: optimizelegibility; color: rgb(15, 17, 17); letter-spacing: normal; text-transform: none; font-weight: 700 !important; font-size: 1.25rem !important; line-height: 24px !important; font-family: &quot;Amazon Ember&quot; !important;\">About this item</h2><ul class=\"a-unordered-list a-vertical a-spacing-mini\" style=\"margin-right: 0px; margin-left: 18px; color: rgb(15, 17, 17); padding-top: 0px; padding-bottom: 0px; font-family: &quot;Amazon Ember&quot;, Arial, sans-serif; font-weight: 400; letter-spacing: normal;\"><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">【14.0-inch diagonal, HD Display】The business and leisure activities will undoubtedly benefit from the mesmerizing clarity and brilliance.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">【Intel Processor N150】Experience a perfect balance of performance and efficiency with a powerful processor, delivering smooth multitasking, reliable performance, and impressive power savings, making it an excellent choice for everyday computing tasks.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">【4GB DDR4 RAM】Get high-bandwidth performance for resource-intensive tasks. Run multiple applications at once and stay responsive.【288GB Storage】128GB UFS + 160GB Docking Station Set. Massive storage space for your files, applications, and multimedia content, providing fast and reliable data access.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">【1 Year Office 365】Take your productivity and work mobility to the next level with the Microsoft 365 Office Suite (1 year subscription included).【Intel Graphics】Enjoy solid image quality that brings your everyday content to life with vibrant colors and sharp details.【Wi-Fi 6】Experience blazing-fast speed, reduced latency, and uninterrupted performance for seamless online gaming.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">【Windows 11】12.76 x 8.86 x 0.71 inches, 3.24 lbs.【Ports】1x USB Type-C, 2x USB Type-A, 1x Headphone/microphone combo, 1x Media card reader, 1x HDMI 1.4b, 1x AC Smart pin. Wi-Fi 6, Bluetooth, Webcam.【Bonus Docking Station Set】1x 7-in-1 Docking Station w/ 128GB Storage, 1x 32GB MicroSD Card w/ Adapter, 1x Type-C Data Cable, 1x 3-in-1 Charging Cable, 1x Suede Cleaning Cloth.</span></li></ul>',128,'en','2025-10-11 18:02:41','2025-10-11 18:02:41'),(429,'P لابتوب فلاج شيب 14 انش HD للطلاب والاعمال','<h2 class=\"a-size-base-plus a-text-bold\" style=\"padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding-block-end: 0.25rem; text-rendering: optimizelegibility; color: rgb(15, 17, 17); letter-spacing: normal; text-transform: none; font-weight: 700 !important; font-size: 1.25rem !important; line-height: 24px !important; font-family: &quot;Amazon Ember&quot; !important;\">عن هذه السلعة</h2><ul class=\"a-unordered-list a-vertical a-spacing-mini\" style=\"margin-right: 18px; margin-left: 0px; color: rgb(15, 17, 17); padding-top: 0px; padding-bottom: 0px; font-family: &quot;Amazon Ember&quot;, Arial, sans-serif; font-weight: 400; letter-spacing: normal;\"><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">【شاشة عرض عالية الدقة بقطر 14.0 انش】ستستفيد أنشطة العمل والترفيه بلا شك من الوضوح والتألق الساحر.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">【معالج انتل N150】استمتع بتوازن مثالي بين الأداء والكفاءة مع معالج قوي، مما يوفر تعدد المهام بسلاسة وأداء موثوق وتوفير طاقة مذهل، مما يجعله خيارًا ممتازًا لمهام الحوسبة اليومية.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">【ذاكرة رام DDR4 سعة 4 جيجابايت】احصل على أداء عرض النطاق الترددي العالي للمهام كثيفة الموارد. قم بتشغيل تطبيقات متعددة في وقت واحد وابق متجاوبًا.【تخزين 288 جيجابايت】مجموعة قاعدة شحن يو اف اس 128 جيجابايت + 160 جيجابايت. مساحة تخزين ضخمة لملفاتك وتطبيقاتك ومحتوى الوسائط المتعددة، مما يوفر وصولاً سريعًا وموثوقًا للبيانات.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">【اوفيس 365 لمدة عام واحد】ارتقِ بإنتاجيتك وحركتك في العمل إلى المستوى التالي مع مايكروسوفت 365 اوفيس سويت (يتضمن اشتراك لمدة عام واحد).【بطاقة رسومات انتل】استمتع بجودة صورة ثابتة تجعل المحتوى اليومي ينبض بالحياة بألوان نابضة بالحياة وتفاصيل حادة. 【واي فاي 6】استمتع بسرعة فائقة ووقت استجابة منخفض وأداء مستمر للعب سلس عبر الإنترنت.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">【ويندوز 11】12.76 × 8.86 × 0.71 انش، 3.39 باوند【المنافذ】1 × USB نوع C، 2 × USB نوع A، 1 × مجموعة سماعة رأس/ميكروفون، 1 × قارئ بطاقات الوسائط، 1 × HDMI 1.4b، 1 × دبوس ذكي بتيار متردد. واي فاي 6، بلوتوث، كاميرا ويب.【مجموعة قاعدة شحن إضافية】1 × قاعدة شحن 7 في 1 مع مساحة تخزين 128 جيجابايت، 1 × بطاقة مايكرو اس دي 32 جيجابايت مع محول، 1 × كيبل بيانات من النوع سي، 1 × كابل شحن 3 في 1، 1 × قطعة قماش للتنظيف من الشامواه.</span></li></ul>',128,'ar','2025-10-11 18:02:41','2025-10-11 18:02:41'),(430,'ASUS ROG Strix G16 (2025) Gaming Laptop','<h2 class=\"a-size-base-plus a-text-bold\" style=\"padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding-block-end: 0.25rem; text-rendering: optimizelegibility; color: rgb(15, 17, 17); letter-spacing: normal; text-transform: none; font-weight: 700 !important; font-size: 1.25rem !important; line-height: 24px !important; font-family: &quot;Amazon Ember&quot; !important;\">About this item</h2><h2 class=\"a-size-base-plus a-text-bold\" style=\"padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding-block-end: 0.25rem; text-rendering: optimizelegibility; color: rgb(15, 17, 17); letter-spacing: normal; text-transform: none; font-weight: 700 !important; font-size: 1.25rem !important; line-height: 24px !important; font-family: &quot;Amazon Ember&quot; !important;\"><ul class=\"a-unordered-list a-vertical a-spacing-mini\" style=\"margin-right: 0px; margin-left: 18px; padding-top: 0px; padding-bottom: 0px; font-family: &quot;Amazon Ember&quot;, Arial, sans-serif; font-size: 14px; font-weight: 400;\"><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">HIGH-LEVEL PERFORMANCE – Unleash power with Windows 11 Home, an Intel Core i7 Processor 14650HX, and an NVIDIA GeForce RTX 5060 Laptop GPU powered by the NVIDIA Blackwell architecture and featuring DLSS 4 and Max-Q technologies.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">FAST MEMORY AND STORAGE – Multitask seamlessly with 16GB of DDR5-5600MHz memory and store all your game library on 1TB of PCIe Gen 4 SSD.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">DYNAMIC DISPLAY AND SMOOTH VISUALS – Immerse yourself in stunning visuals with the smooth 165Hz FHD+ display for gaming, creation, and entertainment. Featuring a new ACR film that enhances contrast and reduces glare.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">STATE-OF-THE-ART ROG INTELLIGENT COOLING – ROG’s advanced thermals keep your system cool, quiet and comfortable. State of the art cooling equals best in class performance. Featuring an end-to-end vapor chamber, tri-fan technology and Conductonaut extreme liquid metal applied to the chipset delivers fast gameplay.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">FULL-SURROUND RGB LIGHTBAR, YOUR WAY – Showcase your style with a 360° RGB light bar that syncs with your keyboard and ROG peripherals. In professional settings, Stealth Mode turns off all lighting for a sleek, refined look.</span></li></ul></h2>',129,'en','2025-10-11 18:11:42','2025-10-11 18:11:42'),(431,'اسس لابتوب العاب روج ستريكس G16 (2025)،','<h2 class=\"a-size-base-plus a-text-bold\" style=\"padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding-block-end: 0.25rem; text-rendering: optimizelegibility; color: rgb(15, 17, 17); letter-spacing: normal; text-transform: none; font-weight: 700 !important; font-size: 1.25rem !important; line-height: 24px !important; font-family: &quot;Amazon Ember&quot; !important;\">عن هذه السلعة</h2><ul class=\"a-unordered-list a-vertical a-spacing-mini\" style=\"margin-right: 18px; margin-left: 0px; color: rgb(15, 17, 17); padding-top: 0px; padding-bottom: 0px; font-family: &quot;Amazon Ember&quot;, Arial, sans-serif; font-weight: 400; letter-spacing: normal;\"><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">أداء عالي المستوى - أطلق العنان للطاقة مع ويندوز 11 هوم، ومعالج انتل كور i7 14650HX، ووحدة معالجة الرسومات الجرافيكية انفيديا جيفورس RTX 5060 التي تعمل ببنية انفيديا بلاكويل وتتميز بتقنيات دي ال اس اس 4 وماكس كيو.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">ذاكرة وتخزين سريعان - تعدد المهام بسلاسة مع ذاكرة DDR5-5600MHz بسعة 16 جيجابايت وتخزين جميع مكتبة الألعاب الخاصة بك على 1 تيرابايت من SSD بمنفذ PCIe الجيل الرابع.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">شاشة ديناميكية ومرئيات سلسة - اغمر نفسك في صور مذهلة مع شاشة FHD عالية الدقة بالكامل 165Hz للألعاب والإبداع والترفيه. يتميز بطبقة ايه سي ار جديدة تعزز التباين وتقلل من الوهج.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">تبريد ذكي متطور من روج - تحافظ الحرارة المتقدمة من روج على نظامك باردًا وهادئًا ومريحًا. تبريد حديث يساوي أفضل أداء في فئته. تتميز بغرفة بخار من طرف إلى طرف، وتقنية المروحة الثلاثية ومعدن سائل كونكتونوت اكستريم المطبق على الشرائح مما يوفر لعبًا سريعًا.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">شريط إضاءة RGB كامل محيطي، طريقتك - أظهر أسلوبك مع شريط إضاءة RGB بزاوية 360 درجة والذي يتزامن مع لوحة المفاتيح وأجهزة روج الطرفية. في الإعدادات الاحترافية، يقوم وضع ستيلث بإيقاف تشغيل جميع الإضاءة للحصول على مظهر أنيق وأنيق.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">قم بالترقية مع إمكانية الوصول بدون أدوات - انس أمر مفك البراغي، وقم بتخصيص ذاكرة الوصول العشوائي وSSD والمراوح عن طريق تحريك مزلاج في النصف السفلي من الجهاز. إطار قابل للإزالة يحمي الأجهزة الأخرى ويوفر وصولاً أعمق للمستخدمين المتقدمين.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">مفتاح موكس مع اوبتيموس متطور - يعزز مفتاح مكس أداء الألعاب بنسبة 5-10% عن طريق توجيه الإطارات مباشرة من وحدة معالجة الرسومات الجرافيكية. تعمل تقنية اوبتيموس المتقدمة على تحسين عمر البطارية من خلال التبديل التلقائي بين وحدة معالجة الرسومات الجرافيكية ووحدة معالجة الرسومات الجرافيكية بناءً على المهمة، دون إعادة التشغيل.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">يتضمن بطاقة لعب للكمبيوتر لمدة 3 أشهر - استمتع بتمرير مجاني لمدة 3 أشهر والوصول إلى أكثر من 100 لعبة عالية الجودة. مع إضافة ألعاب جديدة بانتظام، هناك دائمًا شيء جديد للعب</span></li></ul>',129,'ar','2025-10-11 18:11:42','2025-10-11 18:11:42'),(432,'MSI Katana 15 HX 15.6” 165Hz QHD','<h2 class=\"a-size-base-plus a-text-bold\" style=\"padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding-block-end: 0.25rem; text-rendering: optimizelegibility; color: rgb(15, 17, 17); letter-spacing: normal; text-transform: none; font-weight: 700 !important; font-size: 1.25rem !important; line-height: 24px !important; font-family: &quot;Amazon Ember&quot; !important;\">About this item</h2><ul class=\"a-unordered-list a-vertical a-spacing-mini\" style=\"margin-right: 0px; margin-left: 18px; color: rgb(15, 17, 17); padding-top: 0px; padding-bottom: 0px; font-family: &quot;Amazon Ember&quot;, Arial, sans-serif; font-weight: 400; letter-spacing: normal;\"><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">Unleash Gaming Dominance: Elevate your gaming with the Intel Core i9 processor (14th gen HX-series). Packed with a high core count and lightning-fast speeds, this gaming engine delivers the speed and responsiveness you\'ve been longing for.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">Simplistic Design: Enjoy the latest generation of Windows 11 Home for your everyday needs. *MSI recommends Windows 11 Pro for business use.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">NVIDIA GeForce RTX 5070 Laptop GPU</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">QHD+ Display: The 15.6” 165 Hz QHD+ display brings more vivid colors and pixel density for the ultimate gaming experience.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">Powerful Cooling: Cooler Boost 5 to ensure optimal thermal dissipation and provide the best gaming experience.</span></li></ul>',130,'en','2025-10-11 18:23:14','2025-10-11 18:23:14'),(433,'MSI لابتوب العاب كاتانا 15 HX 15.6 انش 165Hz QHD','<h2 class=\"a-size-base-plus a-text-bold\" style=\"padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding-block-end: 0.25rem; text-rendering: optimizelegibility; color: rgb(15, 17, 17); letter-spacing: normal; text-transform: none; font-weight: 700 !important; font-size: 1.25rem !important; line-height: 24px !important; font-family: \"Amazon Ember\" !important;\">عن هذه السلعة</h2><ul class=\"a-unordered-list a-vertical a-spacing-mini\" style=\"margin-right: 18px; margin-left: 0px; color: rgb(15, 17, 17); padding-top: 0px; padding-bottom: 0px; font-family: \"Amazon Ember\", Arial, sans-serif; font-weight: 400; letter-spacing: normal;\"><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">أطلق العنان لهيمنة الألعاب: ارتقِ بمستوى ألعابك باستخدام معالج انتل كور i9 (الجيل الرابع عشر من سلسلة اتش اكس). مزود بعدد نواة عالي وسرعات فائقة السرعة، يوفر محرك الألعاب هذا السرعة والاستجابة التي كنت تتوق إليها.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">تصميم بسيط: استمتع بأحدث جيل من ويندوز 11 هوم لتلبية احتياجاتك اليومية. *توصي MSI بنظام التشغيل Windows 11 Pro للاستخدام التجاري.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">وحدة معالجة الرسومات الجرافيكية للابتوب انفيديا جيفورس RTX 5070</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">شاشة QHD+ مقاس 15.6 انش 165 هرتز كيو اتش دي + توفر ألوانًا أكثر حيوية وكثافة بكسل لتجربة لعب مثالية.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">تبريد قوي: كولر بوست 5 لضمان تبديد الحرارة الأمثل وتوفير أفضل تجربة ألعاب.</span></li></ul>',130,'ar','2025-10-11 18:23:14','2025-10-11 18:23:14'),(436,'I25 Ultra: Powerhouse 16GB/512GB, 2-Day 7000mAh Battery,','<h2 class=\"a-size-base-plus a-text-bold\" style=\"padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding-block-end: 0.25rem; text-rendering: optimizelegibility; color: rgb(15, 17, 17); letter-spacing: normal; text-transform: none; font-weight: 700 !important; font-size: 1.25rem !important; line-height: 24px !important; font-family: &quot;Amazon Ember&quot; !important;\">About this item</h2><ul class=\"a-unordered-list a-vertical a-spacing-mini\" style=\"margin-right: 0px; margin-left: 18px; color: rgb(15, 17, 17); padding-top: 0px; padding-bottom: 0px; font-family: &quot;Amazon Ember&quot;, Arial, sans-serif; font-weight: 400; letter-spacing: normal;\"><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">Bullet Point 1: The I25 Ultra delivers flagship-level performance without compromise, anchored by its generous 16GB RAM and 512GB storage. This combination ensures lightning-fast responsiveness, effortless handling of the most demanding games and professional applications, and ample space for your entire media library, work files, and apps. Forget the limitations of 12GB RAM – experience true multitasking freedom where apps stay ready in the background, heavy workflows are smooth, and the system feels consistently snappy even under pressure. Paired with the efficient power of Android 14, it\'s a performance beast designed to handle anything you throw at it today and tomorrow.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">Bullet Point 2: Elevate your viewing and interaction with the stunning 6.99-inch display. This large, vibrant screen transforms your smartphone into an entertainment hub and productivity powerhouse. Enjoy movies and videos with cinematic impact, game with immersive detail, browse the web and read comfortably with less eye strain, and view documents or spreadsheets with clarity. The expansive canvas makes split-screen multitasking,genuinely usable and enhances the precision of the built-in stylus. It\'s not just big; it\'s a high-quality window to your digital world, making every visual experience more engaging and enjoyable.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">Bullet Point 3: Experience the liberating power of the massive 7000mAh battery.This isn\'t just about more hours; it\'s about fundamentally changing your relationship with your phone. Go on weekend trips without packing a charger. Forget the midday scramble for an outlet during heavy use. Stream, game, video call, and navigate all day long with power to spare. Compared to phones needing nightly charges (or more), the I25 Ultra reliably delivers 1.5 to 2+ days of typical use. It\'s the ultimate solution for travelers, busy professionals, gamers, and anyone who values uninterrupted usage and peace of mind. Power anxiety is a thing of the past.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">Bullet Point 4: Stay ahead with Android 14, the most advanced and secure version of Android available. Pre-installed on the I25 Ultra, it offers a polished, intuitive, and feature-rich experience. Benefit from enhanced privacy controls that give you granular permission management, smoother system animations for a premium feel, potential battery life improvements through smarter resource management, and the latest security updates guarding against threats. Android 14 also lays the foundation for future innovations and app compatibility. Choosing the I25 Ultra means choosing the freshest, most capable, and secure Android experience from day one.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">Bullet Point 5: Discover the versatility of the built-in stylus, a feature that unlocks new levels of productivity and creativity. Jot down notes instantly in meetings, brainstorm ideas with sketches, annotate PDFs or screenshots directly, edit photos with pinpoint accuracy, or navigate menus with ease. The convenience of never searching for a separate stylus cannot be overstated. For students taking notes, artists sketching concepts, professionals marking up documents, or anyone who prefers precise input, the integrated stylus adds significant, unique value, making the I25 Ultra a truly all-in-one device.</span></li></ul>',132,'en','2025-10-11 19:00:57','2025-10-11 19:00:57'),(437,'جوال اي جيه بي كيه I25 الترا: باور هاوس 16 جيجا/512 جيجا','<h2 class=\"a-size-base-plus a-text-bold\" style=\"padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding-block-end: 0.25rem; text-rendering: optimizelegibility; color: rgb(15, 17, 17); letter-spacing: normal; text-transform: none; font-weight: 700 !important; font-size: 1.25rem !important; line-height: 24px !important; font-family: &quot;Amazon Ember&quot; !important;\">عن هذه السلعة</h2><ul class=\"a-unordered-list a-vertical a-spacing-mini\" style=\"margin-right: 18px; margin-left: 0px; color: rgb(15, 17, 17); padding-top: 0px; padding-bottom: 0px; font-family: &quot;Amazon Ember&quot;, Arial, sans-serif; font-weight: 400; letter-spacing: normal;\"><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">نقطة بوليت 1: يوفر I25 الترا أداءً رائدًا دون تنازلات، مدعوم بذاكرة رام سعة 16 جيجابايت وسعة تخزين 512 جيجابايت. يضمن هذا المزيج استجابة سريعة للغاية، والتعامل بدون عناء مع الألعاب الأكثر تطلبًا والتطبيقات الاحترافية، ومساحة واسعة لمكتبة الوسائط بأكملها وملفات العمل والتطبيقات. انسَ قيود ذاكرة الوصول العشوائي بسعة 12 جيجابايت - استمتع بحرية حقيقية في تعدد المهام حيث تظل التطبيقات جاهزة في الخلفية، وسير العمل الثقيل سلسًا، ويشعر النظام بالسرعة باستمرار حتى تحت الضغط. إلى جانب القوة الفعالة لنظام اندرويد 14، إنه وحش أداء مصمم للتعامل مع أي شيء ترميه عليه اليوم وغدًا.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">نقطة الرصاصة 2: ارتقِ بمشاهدتك وتفاعلك مع شاشة العرض المذهلة مقاس 7 انش. تعمل هذه الشاشة الكبيرة النابضة بالحياة على تحويل هاتفك الذكي إلى مركز ترفيهي وقوة إنتاجية. استمتع بالأفلام ومقاطع الفيديو ذات التأثير السينمائي، والعب بتفاصيل غامرة، وتصفح الويب واقرأ بشكل مريح مع إجهاد أقل للعين، واعرض المستندات أو جداول البيانات بوضوح. القماش الواسع يجعل الشاشة المنقسمة متعددة المهام وقابلة للاستخدام حقًا وتعزز دقة القلم المدمج. إنها ليست كبيرة فقط؛ إنها نافذة عالية الجودة لعالمك الرقمي، مما يجعل كل تجربة بصرية أكثر جاذبية ومتعة.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">نقطة الرصاصة 3: جرب القوة التحريرية للبطارية الضخمة 7000 مللي أمبير في الساعة. هذا ليس فقط ساعات أكثر؛ بل يتعلق بتغيير علاقتك بهاتفك بشكل أساسي. اذهب في رحلات نهاية الأسبوع دون تعبئة شاحن. انس التدافع في منتصف النهار للحصول على منفذ أثناء الاستخدام المكثف. قم بالبث واللعب ومكالمات الفيديو والتنقل طوال اليوم مع توفير الطاقة. بالمقارنة مع الهواتف التي تحتاج إلى شحن ليلي (أو أكثر)، يوفر I25 الترا بشكل موثوق من 1.5 إلى 2+ يوم من الاستخدام العادي. إنه الحل الأمثل للمسافرين والمحترفين المشغولين واللاعبين وأي شخص يقدر الاستخدام المتواصل وراحة البال. القلق القوي هو شيء من الماضي.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">رصاصة بوينت 4: ابق في المقدمة مع اندرويد 14، الإصدار الأكثر تقدمًا وأمانًا من اندرويد المتاح. مثبت مسبقًا على I25 الترا، ويوفر تجربة مصقولة وبديهية وغنية بالميزات. استفد من عناصر التحكم المحسنة في الخصوصية التي تمنحك إدارة أذونات دقيقة، ورسوم متحركة أكثر سلاسة للنظام للحصول على شعور ممتاز، وتحسينات محتملة في عمر البطارية من خلال إدارة أكثر ذكاءً للموارد، وآخر تحديثات الأمان التي تحمي من التهديدات. كما يضع اندرويد 14 الأساس للابتكارات المستقبلية وتوافق التطبيقات. اختيار I25 الترا يعني اختيار تجربة اندرويد الأحدث والأكثر قدرة وأمانًا من اليوم الأول.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">نقطة 5: اكتشف تعدد استخدامات القلم المدمج، وهي ميزة تفتح مستويات جديدة من الإنتاجية والإبداع. قم بتدوين الملاحظات على الفور في الاجتماعات أو تبادل الأفكار باستخدام الرسومات أو التعليق على ملفات PDF أو لقطات الشاشة مباشرة أو تحرير الصور بدقة فائقة أو التنقل في القوائم بسهولة. لا يمكن المبالغة في راحة عدم البحث عن قلم منفصل. بالنسبة للطلاب الذين يدون الملاحظات أو الفنانين الذين يرسمون المفاهيم أو المحترفين في وضع علامات على المستندات أو أي شخص يفضل الإدخال الدقيق، يضيف القلم المدمج قيمة كبيرة وفريدة من نوعها، مما يجعل I25 الترا جهازًا الكل في واحد حقًا.&nbsp;</span></li></ul>',132,'ar','2025-10-11 19:00:57','2025-10-11 19:00:57'),(438,'Samsung Galaxy A16 4G LTE (128GB + 4GB) International','<ul class=\"a-unordered-list a-vertical a-spacing-mini\" style=\"margin-right: 0px; margin-left: 18px; color: rgb(15, 17, 17); padding-top: 0px; padding-bottom: 0px; font-family: \"Amazon Ember\", Arial, sans-serif; font-weight: 400; letter-spacing: normal;\"><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">4G LTE Bands: 1, 2, 3, 4, 5, 7, 8, 12, 17, 20, 28, 38, 40, 41, 66</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">Display: Super AMOLED, 90Hz, 800 nits (HBM) | 6.7 inches, 110.2 cm2 (~86.0% screen-to-body ratio) | 1080 x 2340 pixels, 19.5:9 ratio (~385 ppi density)</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">Camera: 50 MP, f/1.8, (wide), 1/2.76\", 0.64µm, AF | 50 MP, f/1.8, (wide), 1/2.76\", 0.64µm, AF | 2 MP, f/2.4, (macro)</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">Battery: 5000 mAh, non-removable | 25W wired</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">this device does not support E-SIM. This device is compatible with Verizon, AT&T, and some of their MVNO\'s(Tracfone, Straight Talk, , H2O, Visible, etc.). This device is NOT compatible with T-Mobile, their MVNO\'s(Metro, Ultra, Mint, etc.), and other MVNO\'s(Spectrum, Xfinity, Cricket, etc.). Please contact the seller for more information about carrier compatibility. A power adapter is NOT included.</span></li></ul>',133,'en','2025-10-11 19:11:49','2025-10-11 19:11:49'),(439,'سامسونج جوال جالكسي ايه 16 سلسلة 5G A','<h2 class=\"a-size-base-plus a-text-bold\" style=\"padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding-block-end: 0.25rem; text-rendering: optimizelegibility; color: rgb(15, 17, 17); letter-spacing: normal; text-transform: none; font-weight: 700 !important; font-size: 1.25rem !important; line-height: 24px !important; font-family: \"Amazon Ember\" !important;\">عن هذه السلعة</h2><ul class=\"a-unordered-list a-vertical a-spacing-mini\" style=\"margin-right: 18px; margin-left: 0px; color: rgb(15, 17, 17); padding-top: 0px; padding-bottom: 0px; font-family: \"Amazon Ember\", Arial, sans-serif; font-weight: 400; letter-spacing: normal;\"><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">تفاصيل كريسب. إمكانيات حيوية: تساعد شاشة جالكسي ايه 16 الجيل الخامس فائقة الوضوح مقاس 6.7 انش على إضفاء الحيوية على المحتوى الخاص بك سواء كنت تتحقق من رسائل البريد الإلكتروني أو تقرأ المدونات والوصفات عبر الإنترنت.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">صورة مثالية للذكريات: التقط كل زاوية بوضوح مذهل، من اللقطات الجماعية الكبيرة إلى الصور المقربة، مع الكاميرا ثلاثية العدسات على جالاكسي A16 5G.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">أكثر متانة من أي وقت مضى: خذ يومك بثقة، بفضل المتانة الرائعة لهاتف جالاكسي A16 5G مع تصنيف IP54 المحسن.²</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">أصبحت الرؤى الصحية سهلة: ابق على اتصال بصحتك مع جالكسي ايه 16 الجيل الخامس وفيت 3. تتبع خطواتك ونومك ومعدل ضربات القلب³ ثم شاهد كل ذلك في مكان واحد باستخدام تطبيق سامسونج Health.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">تجربة رائعة. قيمة رائعة: يوفر هاتف جالكسي ايه 16 الجيل الخامس ميزات أساسية وإضافات عملية مصممة لتعزيز حياتك اليومية - كل ذلك بسعر ستحبه.</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">الدفع بسهولة: ادفع بنقرة واحدة، بالإضافة إلى تخزين بطاقاتك وهويتك كلها في تطبيق واحد باستخدام سامسونج Wallet.?</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">ست سنوات من التحديثات. أمان رائع: ست سنوات من تحديثات نظام التشغيل والأمان تعني أنه يمكنك الحفاظ على هاتف جالاكسي A16 5G لفترة أطول، مما يجعله قيمة رائعة لسنوات قادمة.</span></li></ul>',133,'ar','2025-10-11 19:11:49','2025-10-11 19:11:49'),(440,'SAMSUNG Galaxy A25 5G A Series Cell Phone','<h2 class=\"a-size-base-plus a-text-bold\" style=\"padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding-block-end: 0.25rem; text-rendering: optimizelegibility; color: rgb(15, 17, 17); letter-spacing: normal; text-transform: none; font-weight: 700 !important; font-size: 1.25rem !important; line-height: 24px !important; font-family: &quot;Amazon Ember&quot; !important;\">About this item</h2><ul class=\"a-unordered-list a-vertical a-spacing-mini\" style=\"margin-right: 0px; margin-left: 18px; color: rgb(15, 17, 17); padding-top: 0px; padding-bottom: 0px; font-family: &quot;Amazon Ember&quot;, Arial, sans-serif; font-weight: 400; letter-spacing: normal;\"><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">YOUR CONTENT, SUPERSMOOTH: Whether watching shows, playing games or reading online, the ultra-clear, superfluid display¹ of Galaxy A25 5G brings your content to life; Plus, Vision Booster lets you to enjoy the bright 800-nits screen experience</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">CAPTURE AWE-WORTHY CONTENT: Mountain ranges, sunsets, dinners with friends — do the moment justice with the high-resolution cameras of Galaxy A25 5G; The triple-lens camera is ready for every angle, while a 50MP main camera catches all the details</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">STORE MORE &amp; WORRY LESS: With improved internal storage of up to 128GB and up to 1TB² of expandable storage, Galaxy A25 5G makes it easy to keep cherished photos, videos and important files readily accessible whenever you need them</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">STEREO SPEAKERS: Experience sensational sound at your fingertips with Galaxy A25 5G; All new stereo speakers get you fully into the world of your favorite music, films and other content in a way like never before —no matter where you are</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">A DIGITAL WALLET IS ALREADY IN YOUR GALAXY: Carry your essentials conveniently in the digital wallet that’s made for your Galaxy phone and Watch³</span></li></ul>',134,'en','2025-10-11 19:32:58','2025-10-11 19:32:58'),(441,'سامسونج جوال جالكسي ايه 25 من سلسلة 5G A','<h2 class=\"a-size-base-plus a-text-bold\" style=\"padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding-block-end: 0.25rem; text-rendering: optimizelegibility; color: rgb(15, 17, 17); letter-spacing: normal; text-transform: none; font-weight: 700 !important; font-size: 1.25rem !important; line-height: 24px !important; font-family: &quot;Amazon Ember&quot; !important;\">عن هذه السلعة</h2><ul class=\"a-unordered-list a-vertical a-spacing-mini\" style=\"margin-right: 18px; margin-left: 0px; color: rgb(15, 17, 17); padding-top: 0px; padding-bottom: 0px; font-family: &quot;Amazon Ember&quot;, Arial, sans-serif; font-weight: 400; letter-spacing: normal;\"><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">محتواك، فائق النعومة: سواء كنت تشاهد العروض أو تلعب الألعاب أو تقرأ عبر الإنترنت، فإن الشاشة فائقة الوضوح وفائقة السوائل لهاتف جالاكسي A25 5G تجلب المحتوى الخاص بك إلى الحياة؛ بالإضافة إلى ذلك، يتيح لك معزز الرؤية الاستمتاع بتجربة شاشة ساطعة تبلغ 800 وحدة مضيئة في البكسل</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">التقط محتوى جدير بالرعب: سلاسل الجبال وغروب الشمس والعشاء مع الأصدقاء - قم بالعدالة مع الكاميرات عالية الدقة لهاتف جالاكسي A25 5G؛ الكاميرا ثلاثية العدسات جاهزة لكل زاوية، بينما تلتقط الكاميرا الرئيسية بدقة 50 ميجابكسل جميع التفاصيل</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">تخزين أكثر وأقل قلقًا: بفضل سعة التخزين الداخلية المحسنة التي تصل إلى 128 جيجابايت وما يصل إلى 1 تيرابايت مربع من التخزين القابل للتوسيع، فإن هاتف جالكسي ايه 25 الجيل الخامس يجعل من السهل الحفاظ على الصور ومقاطع الفيديو والملفات المهمة في متناول اليد كلما احتجت إليها</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">مكبرات صوت ستيريو: جرب الصوت المثير في متناول يدك مع جالكسي ايه 25 الجيل الخامس 5G؛ جميع مكبرات الصوت الستيريو الجديدة تنقلك بالكامل إلى عالم الموسيقى والأفلام والمحتويات الأخرى المفضلة لديك بطريقة لم يسبق لها مثيل - بغض النظر عن مكان وجودك</span></li><li class=\"a-spacing-mini\" style=\"list-style: disc; overflow-wrap: break-word; margin: 0px;\"><span class=\"a-list-item\">محفظة رقمية موجودة بالفعل في جالكسي الخاص بك: احمل ضرورياتك بشكل مريح في المحفظة الرقمية المصممة لهاتف جالكسي وساعتك³</span></li></ul>',134,'ar','2025-10-11 19:32:58','2025-10-11 19:32:58'),(442,'HONOR X6c 6GB RAM 128GB Storage','<h1 class=\"a-size-base-plus a-text-bold\" style=\"padding: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding-block-end: 0.25rem; text-rendering: optimizelegibility; color: rgb(15, 17, 17); letter-spacing: normal; tex